+      objects.set(key, bytes.slice());
+      return "created";
+    },
+    async read({ key }) {
+      const bytes = objects.get(key);
+      if (!bytes) throw new Error("missing");
+      return bytes.slice();
+    },
+    async delete(key) {
+      objects.delete(key);
+    },
+  };
