+  table_name text;
+BEGIN
+  FOREACH table_name IN ARRAY ARRAY[
+    'skills',
+    'skill_versions',
+    'skill_version_files',
+    'skill_contexts',
+    'context_knowledge_revisions',
+    'context_notes',
