+      'CREATE TRIGGER %I BEFORE INSERT OR UPDATE OR DELETE ON %I '
+      || 'FOR EACH ROW EXECUTE FUNCTION skillplane_fence_legacy_workspace_write()',
+      'fence_legacy_workspace_write_' || table_name,
+      table_name
+    );
+  END LOOP;
+END;
+$$;
