+  enabled boolean NOT NULL DEFAULT true,
+  updated_at timestamptz NOT NULL DEFAULT now(),
+  CONSTRAINT workspace_regions_id_valid
+    CHECK (region_id ~ '^[a-z0-9][a-z0-9-]{0,62}$')
+);
+
+INSERT INTO workspace_regions (region_id)
+VALUES ('legacy')
+ON CONFLICT (region_id) DO NOTHING;
+
+ALTER TABLE regional_projection_outbox
+  ADD CONSTRAINT regional_projection_outbox_sequence_positive
+  CHECK (sequence > 0);
+
+ALTER TABLE regional_workspace_migration_fences
+  ADD COLUMN active_epoch bigint NOT NULL DEFAULT 1
+    CHECK (active_epoch > 0);
+
+UPDATE regional_workspace_migration_fences
+   SET active_epoch = GREATEST(active_epoch, source_epoch, 1);
+
+DO $$
+BEGIN
+  IF to_regclass('public.regional_projection_outbox') IS NOT NULL
+     AND to_regclass('public.public_skill_projections') IS NOT NULL
+     AND EXISTS (
+       SELECT 1 FROM regional_projection_outbox WHERE processed_at IS NULL
+     ) THEN
+    RAISE EXCEPTION 'regional projection outbox must be drained before enabling control ordering'
+      USING ERRCODE = '55000';
+  END IF;
+END;
+$$;
+
+CREATE OR REPLACE FUNCTION skillplane_fence_workspace_migration_write()
